// action_score.rs:520
fn calculate_jungle_action_score(_rnd, player, data, _parameter, _action, effect, t) -> i64 {

// L522 — 점수를 내는 주체(자기 챔피언) 획득
  team = player[+0x930] as usize            // len=2 bounds check, 넘으면 panic_bounds_check
  pos  = Position::as_index(player[+0x9c0]) // 0..4 (entity.rs:580-581 인라인)
  champ = (*(data+0x0))[+0x1e0][team][pos]  // Option<&Entity>
  if champ == None { unwrap_failed() }      // option.rs:1011/1013 인라인

// L523 — 이 이펙트가 대상 t 에게 줄 것으로 기대되는 피해량
  value = Effect::expected_damage_target(effect, *(data+0x8), champ, <static 88B>, t)

// L524
  hp = t[+0x670]                            // 대상 현재 HP (i64)

// L526~536 — 대상 종류별 계수 (LLVM 이 술어 체인을 판별자 switch 로 접었다)
  disc = t.entity_type 판별자 = t[+0x68]     // i64, [0,14)
  coef = match disc {
    3 => 200,                               // is_nexus() 로 추정 (L526 에 is_nexus 가 인라인됨)
    2 => 80,                                // L528. 술어 이름 미확인
    4 if t[+0x98] < 2 =>                    // L530 = EntityType::is_jungle() (entity.rs:1377-1378)
           if hp > value { 20 } else { 40 } // L531 — 죽일 수 있으면(피해>=HP) 40, 못 죽이면 20
    4 => 0,                                 // 판별자 4 이지만 payload>=2 (정글 아님)
    1 => -10,                               // 때릴수록 손해로 보는 대상
    _ => 0,                                 // L536
  }

// L542 — 비율과 무관한 고정 가산점
  based = if is_jungle(t.entity_type) { 5 } else { 0 }   // = (disc==4 && t[+0x98]<2)

// L548~549 — 최종 점수
  if hp == 0 { panic_const_div_by_zero() }
  if hp == -1 && coef*value == i64::MIN { panic_const_div_overflow() }
  return min(coef, coef * value / hp) + based     // core::cmp::Ord::min (cmp.rs:1073/1078)
}

// 의미 해석:
//   coef*value/hp = 계수 x (예상피해 / 대상HP) = 대상 체력의 몇 퍼센트를 깎느냐로 계수를 비례 배분.
//   min(coef, ...) 은 비율이 1을 넘어도(오버킬) 양수 계수를 계수값으로 캡한다.
//   반대로 coef 가 음수(-10)면 비율<=1 인 동안 min 은 항상 -10 로 고정되고,
//   오버킬(value>hp)일 때만 -10 보다 더 낮아진다 = 판별자 1 대상에 과잉투자하면 더 감점.
//   반환 상한 205 = 200(넥서스 계수) + 5(정글 가산점) 로, LLVM range 속성과 일치한다.
